files.content:
:root {
  --bg: #1a1c2c;
  --card-bg: #2d2f45;
  --text: #f4f4f4;
  --accent: #ffcd75;
  --accent-dark: #e0a800;
  --input-bg: #3e4058;
  --border: #5a5d7a;
  --underweight: #4fc3f7;
  --normal: #81c784;
  --overweight: #ffb74d;
  --obese: #e57373;
  --error: #ef5350;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, #22243a 25%, transparent 25%),
    linear-gradient(-45deg, #22243a 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #22243a 75%),
    linear-gradient(-45deg, transparent 75%, #22243a 75%);
  background-size: 20px 20px;
  background-position: 0 0, 0 10px, 10px -10px, -10px 0px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
}

h1 {
  font-size: 2rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 8px;
}

.subtitle {
  font-size: 1rem;
  color: #b0b3c8;
  margin-bottom: 24px;
}

.field {
  text-align: left;
  margin-bottom: 16px;
}

label {
  display: block;
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--text);
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-size: 1.125rem;
  font-family: inherit;
  color: var(--text);
  background: var(--input-bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input[type="number"]:hover {
  border-color: #7a7d9a;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 205, 117, 0.3);
}

input[type="number"]::placeholder {
  color: #7a7d9a;
}

.btn {
  display: block;
  width: 100%;
  padding: 14px;
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  font-family: inherit;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--accent-dark);
  border-radius: 0;
  cursor: pointer;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
  transition: transform 0.1s, box-shadow 0.1s, background 0.15s;
  margin-top: 8px;
}

.btn:hover {
  background: #ffd98a;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(4px, 4px);
  box-shadow: none;
}

.result {
  margin-top: 24px;
  padding: 16px;
  background: var(--input-bg);
  border: 3px solid var(--border);
}

.bmi-value {
  font-size: 3rem;
  font-weight: 700;
  line-height: 1;
  color: var(--accent);
}

.bmi-category {
  font-size: 1.25rem;
  font-weight: 600;
  margin-top: 8px;
  text-transform: capitalize;
}

.bmi-category.underweight { color: var(--underweight); }
.bmi-category.normal { color: var(--normal); }
.bmi-category.overweight { color: var(--overweight); }
.bmi-category.obese { color: var(--obese); }

.error {
  margin-top: 16px;
  font-size: 1rem;
  color: var(--error);
  font-weight: 600;
}

@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .bmi-value {
    font-size: 2.5rem;
  }
}

document.addEventListener('DOMContentLoaded', function () {
  var form = document.getElementById('bmi-form');
  var heightInput = document.getElementById('height');
  var weightInput = document.getElementById('weight');
  var resultDiv = document.getElementById('result');
  var bmiNumber = document.getElementById('bmi-number');
  var bmiCategory = document.getElementById('bmi-category');
  var errorMessage = document.getElementById('error-message');

  function getCategory(bmi) {
    if (bmi < 18.5) return 'underweight';
    if (bmi < 25) return 'normal';
    if (bmi < 30) return 'overweight';
    return 'obese';
  }

  function showError(message) {
    resultDiv.hidden = true;
    errorMessage.textContent = message;
    errorMessage.hidden = false;
  }

  function clearError() {
    errorMessage.textContent = '';
    errorMessage.hidden = true;
  }

  function calculateBMI() {
    clearError();

    var height = parseFloat(heightInput.value);
    var weight = parseFloat(weightInput.value);

    if (isNaN(height) || isNaN(weight) || height <= 0 || weight <= 0) {
      showError('Please enter valid positive numbers for height and weight.');
      return;
    }

    var heightM = height / 100;
    var bmi = weight / (heightM * heightM);
    var rounded = Math.round(bmi * 10) / 10;
    var category = getCategory(rounded);

    bmiNumber.textContent = rounded.toFixed(1);
    bmiCategory.textContent = category;
    bmiCategory.className = 'bmi-category ' + category;
    resultDiv.hidden = false;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    calculateBMI();
  });
});
